import { useState, useEffect } from "react";
import { Link, Navigate } from "react-router-dom";
import { toast, Bounce } from "react-toastify";
import { ToastContainer} from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { useAuth } from "../../provider/authProvider";
import logo from '../Images/taskaroo.svg'

const Login = () => {
  const [isLoading, setIsLoading] = useState(false);
  const {login, user} = useAuth()
  const [ , setUserLocation] = useState({ latitude: null, longitude: null });
  const [formData, setFormData] = useState({
    username: '',
    password:'',
  });

  const getLocation = () => {
    return new Promise((resolve, reject) => {
      if ("geolocation" in navigator) {
        navigator.geolocation.getCurrentPosition(
          (position) => {
            const { latitude, longitude } = position.coords;
            setUserLocation({ latitude, longitude });
            console.log(`Latitude: ${latitude}, Longitude: ${longitude}`);
            resolve({ latitude, longitude });
          },
          (error) => {
            reject(error);
          }
        );
      } else {
        reject(new Error("Geolocation is not available in this browser."));
      }
    });
  };


const ProceedLogin = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      if (validate()) {
        
        const location = await getLocation();
        const credentials = { ...formData, ...location };
         
        const result = await login(credentials);
         
        if (result.success) {
          toast.success(`Welcome ${result.user.name}`, {
            position: toast.POSITION.TOP_CENTER
          });
           
          // Redirect based on user role
        } else {
          // Handle specific error types
          const errorMessage = result.error || result.msg || 'Login failed. Please try again.';
          
          // Check if it's a validation error (array of errors)
          if (result.errors && Array.isArray(result.errors)) {
            const validationErrors = result.errors.map(err => err.msg).join(', ');
            toast.error(validationErrors, {
              position: toast.POSITION.TOP_CENTER
            });
          } else {
            toast.error(errorMessage, {
              position: toast.POSITION.TOP_CENTER
            });
          }
        }
      }
    } catch (error) {
      console.log('Error: ' + error);
      toast.error('An unexpected error occurred', {
        position: toast.POSITION.TOP_CENTER
      });
    } finally {
      setIsLoading(false);
    }
  };

  const validate = () => {
    let result = true;
    if (formData.username === '' || formData.username === null) {
      result = false;
      toast.warning('Please Enter Username');
    }
    if (formData.password === '' || formData.password === null) {
      result = false;
      toast.warning('Please Enter Password');
    }
    return result;
  };

  // Check if form is valid (all fields filled)
  const isFormValid = () => {
    return formData.username.trim() !== '' && formData.password.trim() !== '';
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  useEffect(() => {
    if (user) {
      // If user is already logged in, redirect them
      window.location.hash = '#/service_form';
    }
  }, [user]);

  if (user) {
    return <Navigate to="/service_form" replace />;
  }

  
  return (
    <div className="min-h-screen flex flex-col bg-teal-50 font-sans overflow-hidden">
      {/* Header */}
      <header className="bg-transparent py-4 sm:py-6 px-4 sm:px-8 flex items-center justify-between flex-shrink-0">
        <div className="back-button">
          <Link to="/">
            <button className="flex items-center text-teal-600 hover:text-teal-800 font-semibold transition-all duration-300 hover:bg-teal-100 px-3 py-2 sm:px-4 sm:py-2 rounded-lg text-sm sm:text-base">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 sm:h-5 sm:w-5 mr-1" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
              </svg>
              <span className="hidden sm:inline">Back to Navigator</span>
              <span className="sm:hidden text-2xl">Back</span>
            </button>
          </Link>
        </div>
        <div className="logo ml-10 sm:ml-10 mt-10 sm:mt-6 flex-shrink-0">
          <img src={logo} alt="Logo" className="max-w-[20rem] xs:max-w-[12rem] sm:max-w-[16rem] lg:max-w-[20rem] drop-shadow-md" />
        </div>
      </header>

      {/* Main Content */}
      <div className="flex-1 flex items-center justify-center p-3 sm:p-4 md:p-6 overflow-y-auto">
        <div className="bg-white border border-lime-200 rounded-xl sm:rounded-2xl shadow-lg shadow-lime-100 p-4 sm:p-6 md:p-8 lg:p-10 w-full max-w-[320px] xs:max-w-xs sm:max-w-sm md:max-w-md mx-auto my-4">
          <h1 className="text-2xl xs:text-2xl sm:text-3xl md:text-4xl font-extrabold text-center text-teal-700 mb-2 tracking-tight">
            Sign In
          </h1>
          <p className="text-slate-600 text-center text-xl font-semibold xs:text-sm sm:text-base mb-4 sm:mb-6 md:mb-8">
            Welcome back! Please enter your details 🌟
          </p>

          <form onSubmit={ProceedLogin}>
            {/* Username */}
            <div className="mb-3 sm:mb-4 md:mb-5">
              <label className="block text-slate-700 font-medium mb-1 sm:mb-2 text-xl xs:text-sm sm:text-base">
                Username<span className="text-rose-500">*</span>
              </label>
              <input
                type="text"
                value={formData.username}
                onChange={handleChange}
                name="username"
                className="w-full px-3 py-2 sm:px-4 sm:py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-teal-400 focus:border-transparent transition text-m sm:text-base"
                placeholder="Enter your username"
              />
            </div>

            {/* Password */}
            <div className="mb-4 sm:mb-5 md:mb-6">
              <label className="block text-slate-700 font-medium mb-1 sm:mb-2 text-xl xs:text-sm sm:text-base">
                Password<span className="text-rose-500">*</span>
              </label>
              <input
                type="password"
                value={formData.password}
                onChange={handleChange}
                name="password"
                className="w-full px-3 py-2 sm:px-4 sm:py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-teal-400 focus:border-transparent transition text-m sm:text-base"
                placeholder="Enter your password"
              />
            </div>

            {/* Sign In Button */}
            <div className="button-container mb-4 sm:mb-5 md:mb-6">
              <button
                type="submit"
                className={`w-full py-2 sm:py-3 px-4 rounded-lg font-semibold text-xl sm:text-base md:text-lg transition-all duration-300 ${
                  isFormValid()
                  ? 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-md'
                  : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                }`}
                disabled={isLoading || !isFormValid()}
              >
                {isLoading ? (
                  <div className="flex items-center justify-center">
                    <div className="animate-spin rounded-full h-3 w-3 sm:h-4 sm:w-4 md:h-5 md:w-5 border-b-2 border-white mr-2"></div>
                      Signing in...
                    </div>
                ) : (
                  'Sign In'
                )}
              </button>
            </div>

            {/* Register Link */}
            <div className="text-center">
              <p className="text-slate-600 text-xl xs:text-sm">
                Don't have an account?
                <Link
                  to="/register"
                  className="text-teal-600 hover:text-emerald-600 font-semibold ml-1 transition-colors"
                >
                  Create account
                </Link>
              </p>
            </div>
          </form>
        </div>
      </div>
 
      {/* Toast Notifications */}
      <ToastContainer
        autoClose={5000}
        hideProgressBar={true}
        newestOnTop={false}
        theme="colored"
        transition={Bounce}
      />
    </div>
  );
};

export default Login