import { Link } from "react-router-dom"
import logo from "./Images/taskaroo.svg"

const Navigator = () => {

    return (
    <>
        {/* Rebranding Announcement Banner */}
        <div className="bg-teal-200 text-white text-center py-1 sm:py-2 px-4 relative z-50">
            <p className="text-xs sm:text-sm font-medium">
                🎉 <strong>Taskify → Taskaroo</strong> 🎉
            </p>
        </div>

        {/* Main container that takes full viewport height */}
        <div className="min-h-screen flex flex-col">
            {/* Header with flexible spacing */}
            <header className="bg-transparent py-2 sm:py-4 lg:py-8 xl:py-12 px-4 flex items-center justify-center flex-shrink-0">
                <div className="logo">
                    <img 
                        src={logo} 
                        alt="Logo" 
                        className="w-48 sm:w-56 md:w-64 lg:w-72 xl:w-80 drop-shadow-md" 
                    />
                </div>
            </header>

            {/* Cards section that grows to fill remaining space and centers content */}
            <div className="flex-1 flex flex-col items-center justify-center bg-transparent px-4 sm:px-6 lg:px-8 pb-4 lg:pb-16 xl:pb-24">
                <div className="flex flex-col sm:flex-row gap-3 sm:gap-6 lg:gap-8 justify-center items-center w-full max-w-4xl">
                    
                    {/* Client Card */}
                    <Link
                        to="/login"
                        className="w-full max-w-[260px] sm:max-w-xs lg:max-w-sm bg-white rounded-lg sm:rounded-xl shadow-md hover:shadow-xl transition-all duration-300 p-3 sm:p-5 lg:p-7 border border-gray-200 hover:border-teal-300 group touch-manipulation active:scale-95"
                    >
                        <div className="text-center">
                            <div className="text-3xl sm:text-4xl lg:text-5xl mb-2 sm:mb-3">👤</div>
                            <h3 className="text-base sm:text-lg lg:text-xl font-bold text-gray-800 group-hover:text-teal-700 transition-colors">
                                Client
                            </h3>
                            <p className="text-xs sm:text-sm text-gray-600 mt-1 sm:mt-2 leading-tight sm:leading-relaxed">
                                Hire skilled freelancers for your tasks
                            </p>
                        </div>
                    </Link>

                    {/* Freelancer Card */}
                    <Link
                        to="/worker_login"
                        className="w-full max-w-[260px] sm:max-w-xs lg:max-w-sm bg-white rounded-lg sm:rounded-xl shadow-md hover:shadow-xl transition-all duration-300 p-3 sm:p-5 lg:p-7 border border-gray-200 hover:border-teal-300 group touch-manipulation active:scale-95"
                    >
                        <div className="text-center">
                            <div className="text-3xl sm:text-4xl lg:text-5xl mb-2 sm:mb-3">🛠️</div>
                            <h3 className="text-base sm:text-lg lg:text-xl font-bold text-gray-800 group-hover:text-teal-700 transition-colors">
                                Freelancer
                            </h3>
                            <p className="text-xs sm:text-sm text-gray-600 mt-1 sm:mt-2 leading-tight sm:leading-relaxed">
                                Offer your skills and earn money
                            </p>
                        </div>
                    </Link>

                </div>
            </div>
        </div>
    </>
);

}

export default Navigator